mapper.select:
SELECT COUNT(*) AS total_members, SUM(CASE WHEN mv.member_sex = 1 THEN 1 ELSE 0 END) AS male_count, SUM(CASE WHEN mv.member_sex = 2 THEN 1 ELSE 0 END) AS female_count, SUM(CASE WHEN mv.member_sex IS NULL OR mv.member_sex NOT IN (1, 2) THEN 1 ELSE 0 END) AS unknown_count, SUM(CASE WHEN exp.total_amount > 0 THEN 1 ELSE 0 END) AS expense_member_count, COALESCE(SUM(exp.total_amount), 0) AS total_expense_amount FROM member_info_view mv LEFT JOIN ( SELECT e.expense_mobile AS mobile, SUM(CAST(NULLIF(TRIM(e.expense_realamt), '') AS DECIMAL(20, 2))) AS total_amount FROM expense_calendar_info e WHERE e.expense_state = '10' AND e.del_flag = '0' AND e.expense_mobile IS NOT NULL GROUP BY e.expense_mobile ) exp ON exp.mobile = mv.member_mobile WHERE mv.del_flag = 0
AND mv.member_tenant = #{tenant}
AND mv.member_allot_store = #{station}
